1|// Reader model: the slim shape the client receives. Joins paragraphs to
2|// scenes by ordinal range in reading order; analysis internals never leave.
3|import type { AnalyzedScene, Book } from "./types";
4|import type { Vector8 } from "./types";
5|
6|export interface ReaderParagraph {
7|  id: string;
8|  n: number;
9|  text: string;
10|  // Set on fragments after the first when paginateScene splits one
11|  // paragraph across pages. Fragments share n; ids stay unique.
12|  cont?: boolean;
13|}
14|
15|export interface ReaderScene {
16|  id: string;
17|  title: string;
18|  emotion: { vector: Vector8; intensity: number; tempo: number } | null;
19|  paragraphs: ReaderParagraph[];
20|}
21|
22|export interface ReaderChapter {
23|  ch: number;
24|  title: string;
25|  scenes: ReaderScene[];
26|}
27|
28|export interface ReaderModel {
29|  bookId: string;
30|  textVersion: string;
31|  title: string;
32|  author: string;
33|  chapters: ReaderChapter[];
34|}
35|
36|// 1280x800 fit: the reading column is 595 px tall and the heading block
37|// (kicker, title, Scene/Page line) takes ~115 px of it on every page,
38|// leaving ~480 px for text. At 20.5px/1.7 each line costs 34.85 px, so a
39|// page holds 13 lines; the ~538 px measure fits ~58 chars per line, so
40|// each paragraph costs ceil(chars / 58) lines and short dialogue lines
41|// each take a full line. Page one also carries the drop cap, so it
42|// budgets one less. Paragraphs stay whole; one over budget takes its own
43|// page.
44|export const PAGE_WORD_BUDGET = 250;
45|const READ_COL_PX = 595;
46|const HEADING_PX = 115;
47|const LINE_PX = 20.5 * 1.7;
48|export const CHARS_PER_LINE = 58;
49|export const LINES_PER_PAGE = Math.floor((READ_COL_PX - HEADING_PX) / LINE_PX);
50|export const FIRST_PAGE_LINES = LINES_PER_PAGE - 1;
51|
52|export interface SubPage {
53|  paragraphs: ReaderParagraph[];
54|  startN: number;
55|  endN: number;
56|  words: number;
57|}
58|
59|export function countWords(text: string): number {
60|  const words = text.split(/\s+/).filter((w) => w.length > 0);
61|  return words.length;
62|}
63|
64|export function estimateLines(text: string): number {
65|  return Math.max(1, Math.ceil(text.length / CHARS_PER_LINE));
66|}
67|
68|// Title measure: ~26 chars per line at the 44 px chapter-title size in
69|// the 538 px column. "The Cyclone" is 1 line,
70|// "The Discovery of Oz, the Terrible" is 2.
71|export const TITLE_CHARS_PER_LINE = 26;
72|const WRAPPED_TITLE_PENALTY = 2;
73|
74|export function chapterTitleLines(title: string): number {
75|  if (title.length === 0) return 1;
76|  return Math.max(1, Math.ceil(title.length / TITLE_CHARS_PER_LINE));
77|}
78|
79|// Latest sentence end (`. `, `! `, `? `, `; `, closing quotes included)
80|// at or before maxChars, as a cut index into text, or -1 when none fits.
81|// The cut sits just past the space, so fragments join back exactly.
82|function sentenceCut(text: string, maxChars: number): number {
83|  const re = /[.!?;]["'”’)\]]* /g;
84|  let cut = -1;
85|  for (;;) {
86|    const m = re.exec(text);
87|    if (m === null) break;
88|    const end = m.index + m[0].length;
89|    if (end > maxChars || end >= text.length) break;
90|    cut = end;
91|  }
92|  return cut;
93|}
94|
95|// Latest cut at or before maxChars that fits maxWords: the sentence cut
96|// when one fits, else the last space, else a hard cut. Backs off to an
97|// earlier space while the prefix holds too many words.
98|function findCut(text: string, maxChars: number, maxWords: number): number {
99|  const cap = Math.min(maxChars, text.length - 1);
100|  let cut = sentenceCut(text, cap);
101|  if (cut <= 0) {
102|    const at = text.lastIndexOf(" ", cap);
103|    // at + 1 can pass maxChars by one char (a 2-line 59-char slip
104|    // into a 1-line slot), so clamp: the space opens the next fragment.
105|    cut = at <= 0 ? cap : Math.min(at + 1, cap);
106|  }
107|  while (cut > 1 && countWords(text.slice(0, cut)) > maxWords) {
108|    const at = text.lastIndexOf(" ", cut - 2);
109|    if (at <= 0) break;
110|    cut = at + 1;
111|  }
112|  return Math.max(1, Math.min(cut, text.length - 1));
113|}
114|
115|// Split one scene into sub-pages: a page closes when the next paragraph
116|// would pass the word budget or the line budget. A paragraph that fits
117|// the remaining budget, or a fresh page when the current one has text,
118|// moves whole. One longer than a full page fills the current page at a
119|// sentence boundary (word boundary fallback) and continues on the next;
120|// fragments share n, later ones carry cont. A wrapped chapter title
121|// costs every page WRAPPED_TITLE_PENALTY lines.
122|export function paginateScene(
123|  paragraphs: ReaderParagraph[],
124|  budgetWords: number = PAGE_WORD_BUDGET,
125|  chapterTitle: string = "",
126|): SubPage[] {
127|  const penalty = chapterTitleLines(chapterTitle) > 1 ? WRAPPED_TITLE_PENALTY : 0;
128|  const budgetFor = (pageIndex: number): number =>
129|    (pageIndex === 0 ? FIRST_PAGE_LINES : LINES_PER_PAGE) - penalty;
130|  const pages: SubPage[] = [];
131|  let current: ReaderParagraph[] = [];
132|  let words = 0;
133|  let lines = 0;
134|  const flush = () => {
135|    if (current.length === 0) return;
136|    pages.push({
137|      paragraphs: current,
138|      startN: current[0]?.n ?? 0,
139|      endN: current[current.length - 1]?.n ?? 0,
140|      words,
141|    });
142|    current = [];
143|    words = 0;
144|    lines = 0;
145|  };
146|  const pushFrag = (p: ReaderParagraph, text: string, fragNo: number) => {
147|    const w = countWords(text);
148|    const l = estimateLines(text);
149|    current.push(
150|      fragNo === 0 ? { id: p.id, n: p.n, text } : { id: `${p.id}~${fragNo + 1}`, n: p.n, text, cont: true },
151|    );
152|    words += w;
153|    lines += l;
154|  };
155|  for (const p of paragraphs) {
156|    let rest = p.text;
157|    let fragNo = 0;
158|    while (rest.length > 0) {
159|      const budget = budgetFor(pages.length);
160|      const remainingLines = budget - lines;
161|      const remainingWords = budgetWords - words;
162|      const wRest = countWords(rest);
163|      const lRest = estimateLines(rest);
164|      if (lRest <= remainingLines && wRest <= remainingWords) {
165|        pushFrag(p, rest, fragNo);
166|        rest = "";
167|      } else if (remainingLines <= 0 || remainingWords <= 0) {
168|        flush();
169|      } else if (current.length > 0 && lRest <= budgetFor(pages.length + 1) && wRest <= budgetWords) {
170|        flush();
171|      } else {
172|        const cut = findCut(rest, remainingLines * CHARS_PER_LINE, remainingWords);
173|        pushFrag(p, rest.slice(0, cut), fragNo);
174|        fragNo += 1;
175|        rest = rest.slice(cut);
176|        flush();
177|      }
178|    }
179|  }
180|  flush();
181|  if (pages.length === 0) pages.push({ paragraphs: [], startN: 0, endN: 0, words: 0 });
182|  return pages;
183|}
184|
185|export interface SceneView {
186|  sceneId: string;
187|  ch: number;
188|  chapterTitle: string;
189|  title: string;
190|  emotion: ReaderScene["emotion"];
191|  pages: SubPage[];
192|  prevSceneId: string | null;
193|  nextSceneId: string | null;
194|  k: number;
195|  n: number;
196|}
197|
198|// The only text a scene route ships: this scene, its chapter, its pages,
199|// and neighbor ids for the pager. Throws on unknown scene id.
200|export function buildSceneView(
201|  model: ReaderModel,
202|  sceneId: string,
203|  budgetWords: number = PAGE_WORD_BUDGET,
204|): SceneView {
205|  const flat = model.chapters.flatMap((c) => c.scenes.map((s) => ({ ch: c.ch, chapterTitle: c.title, scene: s })));
206|  const at = flat.findIndex((e) => e.scene.id === sceneId);
207|  if (at < 0 || !flat[at]) throw new Error(`unknown scene ${sceneId}`);
208|  const entry = flat[at] as { ch: number; chapterTitle: string; scene: ReaderScene };
209|  const chapterScenes = flat.filter((e) => e.ch === entry.ch);
210|  const prev = at > 0 ? flat[at - 1] : null;
211|  const next = at < flat.length - 1 ? flat[at + 1] : null;
212|  return {
213|    sceneId,
214|    ch: entry.ch,
215|    chapterTitle: entry.chapterTitle,
216|    title: entry.scene.title,
217|    emotion: entry.scene.emotion,
218|    pages: paginateScene(entry.scene.paragraphs, budgetWords, entry.chapterTitle),
219|    prevSceneId: prev?.scene.id ?? null,
220|    nextSceneId: next?.scene.id ?? null,
221|    k: chapterScenes.findIndex((e) => e.scene.id === sceneId) + 1,
222|    n: chapterScenes.length,
223|  };
224|}
225|
226|export interface NavState {
227|  sceneId: string;
228|  page: number;
229|}
230|
231|export type NavAction =
232|  | { kind: "next" }
233|  | { kind: "prev" }
234|  | { kind: "goto"; sceneId: string; atEnd?: boolean };
235|
236|export interface NavIndex {
237|  order: string[];
238|  pageCounts: Map<string, number>;
239|}
240|
241|export function buildNavIndex(views: { sceneId: string; pages: number }[]): NavIndex {
242|  return {
243|    order: views.map((v) => v.sceneId),
244|    pageCounts: new Map(views.map((v) => [v.sceneId, v.pages] as [string, number])),
245|  };
246|}
247|
248|// Every pager move in one place: next/prev cross scenes and chapters,
249|// going back lands on the last sub-page, bounds are no-ops, unknown
250|// goto ids keep state.
251|export function navReducer(state: NavState, action: NavAction, index: NavIndex): NavState {
252|  const at = index.order.indexOf(state.sceneId);
253|  if (at < 0) return state;
254|  const pages = index.pageCounts.get(state.sceneId) ?? 1;
255|  if (action.kind === "next") {
256|    if (state.page < pages - 1) return { ...state, page: state.page + 1 };
257|    const nextId = index.order[at + 1];
258|    return nextId === undefined ? state : { sceneId: nextId, page: 0 };
259|  }
260|  if (action.kind === "prev") {
261|    if (state.page > 0) return { ...state, page: state.page - 1 };
262|    const prevId = at > 0 ? index.order[at - 1] : undefined;
263|    if (prevId === undefined) return state;
264|    return { sceneId: prevId, page: (index.pageCounts.get(prevId) ?? 1) - 1 };
265|  }
266|  if (index.order.indexOf(action.sceneId) < 0) return state;
267|  const count = index.pageCounts.get(action.sceneId) ?? 1;
268|  return { sceneId: action.sceneId, page: action.atEnd ? count - 1 : 0 };
269|}
270|
271|// True only when the scene id changed. The container gates observeScene
272|// on this, so sub-page moves never touch the scheduler.
273|export function isSceneEntry(prevSceneId: string | null, nextSceneId: string): boolean {
274|  return prevSceneId !== nextSceneId;
275|}
276|
277|export interface SceneEntryGate {
278|  observedId: string | null;
279|  routeId: string | null;
280|  manifestReady: boolean;
281|}
282|
283|// The container's effect gate in one testable place: observe exactly once
284|// per route id, only after the manifest lands. Route params can lag a
285|// render, so the last observed id is compared before every observe call.
286|export function nextSceneEntry(gate: SceneEntryGate): {
287|  shouldObserve: boolean;
288|  nextObservedId: string | null;
289|} {
290|  if (!gate.routeId || !gate.manifestReady || !isSceneEntry(gate.observedId, gate.routeId)) {
291|    return { shouldObserve: false, nextObservedId: gate.observedId };
292|  }
293|  return { shouldObserve: true, nextObservedId: gate.routeId };
294|}
295|
296|// Throws on unordered scenes and on paragraphs covered zero or two times.
297|export function buildReaderModel(
298|  book: Pick<Book, "id" | "title" | "author" | "chapters" | "paragraphs" | "textVersion">,
299|  analysis: { scenes: AnalyzedScene[] },
300|): ReaderModel {
301|  const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
302|  const scenes = [...analysis.scenes];
303|  for (let i = 1; i < scenes.length; i++) {
304|    const prev = scenes[i - 1];
305|    const cur = scenes[i];
306|    if (prev && cur && (cur.start_n < prev.start_n || (cur.start_n === prev.start_n && cur.end_n < prev.end_n))) {
307|      throw new Error(`scenes out of order at ${cur.id}`);
308|    }
309|  }
310|  const seen = new Set<number>();
311|  const sceneParagraphs = new Map<string, ReaderParagraph[]>();
312|  for (const scene of scenes) {
313|    const paras: ReaderParagraph[] = [];
314|    for (let n = scene.start_n; n <= scene.end_n; n++) {
315|      const p = byN.get(n);
316|      if (!p) throw new Error(`scene ${scene.id} covers missing ordinal ${n}`);
317|      if (seen.has(n)) throw new Error(`ordinal ${n} covered twice`);
318|      seen.add(n);
319|      paras.push({ id: p.id, n: p.n, text: p.text });
320|    }
321|    sceneParagraphs.set(scene.id, paras);
322|  }
323|  if (seen.size !== book.paragraphs.length) {
324|    throw new Error(`coverage gap: ${book.paragraphs.length - seen.size} paragraphs uncovered`);
325|  }
326|  const chapters: ReaderChapter[] = book.chapters.map((chapter) => {
327|    const mine = scenes.filter((s) => s.ch === chapter.ch);
328|    if (mine.some((s) => s.start_n < chapter.start_n || s.end_n > chapter.end_n)) {
329|      throw new Error(`a scene crosses chapter ${chapter.ch} bounds`);
330|    }
331|    return {
332|      ch: chapter.ch,
333|      title: chapter.title,
334|      scenes: mine.map((s) => ({
335|        id: s.id,
336|        title: s.title,
337|        emotion: s.final === null ? null : { ...s.final },
338|        paragraphs: sceneParagraphs.get(s.id) ?? [],
339|      })),
340|    };
341|  });
342|  return {
343|    bookId: book.id,
344|    textVersion: book.textVersion,
345|    title: book.title,
346|    author: book.author,
347|    chapters,
348|  };
349|}

