1|import { buildReaderModel, buildSceneView, PAGE_WORD_BUDGET, paginateScene } from "@/core/reader";
2|import { loadOzBook } from "@/server/books";
3|import { ScenePage } from "../scene-page";
4|
5|// One static route per scene. Unknown ids 404; no other scene text
6|// ships with this view.
7|export const dynamicParams = false;
8|
9|export function generateStaticParams() {
10|  const { book, scenes } = loadOzBook();
11|  const model = buildReaderModel(book, { scenes });
12|  return model.chapters.flatMap((chapter) => chapter.scenes.map((scene) => ({ sceneId: scene.id })));
13|}
14|
15|export default async function SceneRoute({ params }: { params: Promise<{ sceneId: string }> }) {
16|  const { sceneId } = await params;
17|  const { book, scenes } = loadOzBook();
18|  const model = buildReaderModel(book, { scenes });
19|  const view = buildSceneView(model, sceneId);
20|  // Page counts for the pager reducer: ids and numbers only, no text.
21|  const views = model.chapters.flatMap((chapter) =>
22|    chapter.scenes.map((scene) => ({
23|      sceneId: scene.id,
24|      pages: paginateScene(scene.paragraphs, PAGE_WORD_BUDGET, chapter.title).length,
25|    })),
26|  );
27|  const flat = model.chapters.flatMap((chapter) => chapter.scenes.map((scene) => scene.id));
28|  return (
29|    <ScenePage
30|      key={sceneId}
31|      view={view}
32|      views={views}
33|      bookId={model.bookId}
34|      textVersion={model.textVersion}
35|      bookIndex={flat.indexOf(sceneId)}
36|      bookTotal={flat.length}
37|    />
38|  );
39|}

