import { loadOzBook } from "./server/books.ts";
import { buildReaderModel, buildSceneView, estimateLines, INDENT_CHARS, LINES_PER_PAGE, FIRST_PAGE_LINES } from "./core/reader.ts";
const { book, scenes } = loadOzBook();
const model = buildReaderModel(book, { scenes });
const view = buildSceneView(model, "c10s4");
console.log("pages:", view.pages.length);
view.pages.forEach((pg, i) => {
  const budget = i === 0 ? FIRST_PAGE_LINES : LINES_PER_PAGE;
  let lines = 0;
  pg.paragraphs.forEach((p, j) => {
    const indented = j > 0 || i > 0 ? true : false;
    lines += estimateLines(p.text, indented && !p.cont && !(i === 0 && j === 0));
  });
  console.log(`sub-page ${i + 1}: paras=${pg.paragraphs.length} estLines=${lines} budget=${budget} ${lines <= budget ? "OK" : "OVERFLOW"}`);
});
' 2>&1 | tail -10",
